const int MAX_MARCHES = 300;
const float RAYMARCH_THRESHOLD = 0.001;
const float NORMAL_EPSILON = 0.001;

mat2 rot_xy(float theta)
{
    return mat2(cos(theta), sin(theta),
                -sin(theta), cos(theta));
}

vec3 palette(float iter)
{
    return 0.5 + 0.5 * sin(iter + vec3(0, 1, 2));
}

vec4 union_de(vec4 a, vec4 b)
{
    if (b.w < a.w) {
        return b;
    } else {
        return a;
    }
}

float box3d_de(vec3 p, vec3 sizes)
{
    vec3 temp = abs(p) - sizes;
    return length(max(temp, 0.0)) + min(max(max(temp.x, temp.y), temp.z), 0.0);
}

float fractal_de(vec3 p, out float iter)
{
    float scale = 2.0;
    float max_i = floor(mod(iTime + 5.0, 5.99)) + 1.0;
    float s = 1.0;
    float d = 1e6;

    const float width = 1.0;
    const float thickness = 0.05;
    const float r = thickness / 2.0;
    const float a = (width - thickness) / 2.0;
    for (float i = 0.0; i < max_i; i++) {
        vec3 b = abs(p);
        p.xz = b.xz;
        if (b.x < b.y) {
            b.xy = b.yx;
        }
        if (b.y < b.z) {
            b.yz = b.zy;
        }
        if (b.x < b.z) {
            b.xz = b.zx;
        }
        float d1 = box3d_de(b - vec3(a, a, width / 4.0), vec3(r, r, width / 4.0)) * s;
        if (d1 < d) {
            iter = i;
        }
        d = min(d, d1);
        p -= vec3(0.5, -0.3, 0.5);
        p *= scale;
        s /= scale;
    }
    return d;
}

float dist_estim(vec3 p, out vec3 col)
{
    float iter = 0.0;
    float scale = 0.4;
    float fractal = fractal_de(p / scale, iter) * scale;
    vec3 plane_col = vec3(0.5);
    if ((mod(p.x, 1.0) > 0.5) != (mod(p.z, 1.0) > 0.5)) {
        plane_col = vec3(1.0);
    }

    vec4 de = vec4(palette(iter), fractal);
    de = union_de(de, vec4(plane_col, abs(p.y + 0.25)));

    col = de.xyz;
    return de.w;
}

vec3 calc_normal(vec3 p)
{
    const vec2 eps = vec2(0.0, NORMAL_EPSILON);
    vec3 temp = vec3(0.0);
    return normalize(vec3(
        dist_estim(p + eps.yxx, temp),
        dist_estim(p + eps.xyx, temp),
        dist_estim(p + eps.xxy, temp)
        ) - dist_estim(p, temp));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
	uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 col = vec3(0.0);

    vec2 m = iMouse.xy / iResolution.xy;
    if (m.x < 0.01 && m.y < 0.01) {
        m = vec2(0.4, 0.4);
    }
    vec2 rot = (m - 0.5) * 4.0;vec3 ray_dir = normalize(vec3(uv, 2.0));
    mat2 yz_mat = rot_xy(rot.y);
    mat2 xz_mat = rot_xy(rot.x);
    ray_dir.yz *= yz_mat;
    ray_dir.xz *= xz_mat;
    vec3 ray_endpoint = vec3(0.0, 0.0, -1.0);
    ray_endpoint.yz *= yz_mat;
    ray_endpoint.xz *= xz_mat;

    vec3 light_dir = normalize(vec3(0.3, 1.0, -0.5));

    for (int march = 0; march < MAX_MARCHES; march++) {
        vec3 surface_col = vec3(0.0);
        float dist = dist_estim(ray_endpoint, surface_col);
        if (dist < RAYMARCH_THRESHOLD) {
			vec3 norm = calc_normal(ray_endpoint);
            float intensity = max(dot(norm, light_dir), 0.0);
            vec3 light_col = vec3(0.9);
            vec3 ambient = vec3(0.1);
            col = surface_col * (light_col * intensity + ambient);
            break;
        }
        ray_endpoint += ray_dir * dist * 0.5;
    }

    fragColor = vec4(col,1.0);
}
